{"code":"import os, json

# T34: Skill 索引搜索测试
index_path = os.path.expanduser("~/.hermes/skills/skill-search-index.json")
with open(index_path, "r") as f:
    index = json.load(f)

def search_skills(query):
    query = query.lower()
    results = []
    for name, meta in index.items():
        score = 0
        if query in name.lower():
            score += 10
        if query in meta.get("description", "").lower():
            score += 5
        for kw in meta.get("keywords", []):
            if query in kw.lower():
                score += 3
        if score > 0:
            results.append((name, score, meta["confidence"], meta["grade"]))

    results.sort(key=lambda x: x[1], reverse=True)
    return results

# 测试搜索
test_queries = ["github", "deploy", "test", "health", "optimize"]

print("Skill 索引搜索测试:")
print("=" * 60)

for query in test_queries:
    results = search_skills(query)[:3]
    print(f"\n查询: '{query}'")
    if results:
        for name, score, conf, grade in results:
            print(f"  {name:<30} score={score} conf={conf} [{grade}]")
    else:
        print("  (无匹配)")

print("\n" + "=" * 60)
print("✓ 索引搜索功能正常")
